import pytest

if pytest.use_correct:
    from correct_python_programs.possible_change import possible_change
else:
    from python_programs.possible_change import possible_change


def test_attack_1():
    # empty coin list with positive total -> 0 ways, must not crash
    assert possible_change([], 7) == 0


def test_attack_2():
    # empty coin list with zero total -> 1 way (use no coins)
    # pins order of base cases: total==0 must take precedence over empty
    assert possible_change([], 0) == 1


def test_attack_3():
    # docstring example
    assert possible_change([1, 5, 10, 25], 11) == 4


def test_attack_4():
    # single denomination that cannot make total -> must exhaust to empty and return 0
    assert possible_change([2], 3) == 0


def test_attack_5():
    # zero total with non-empty coins -> 1 way
    assert possible_change([3, 7], 0) == 1


def test_attack_6():
    # all coins larger than total -> must skip all and return 0
    assert possible_change([10, 25], 5) == 0


def test_attack_7():
    # order of denominations must not matter
    assert possible_change([1, 5], 6) == 2
    assert possible_change([5, 1], 6) == 2


def test_attack_8():
    # negative total -> 0 ways
    assert possible_change([1, 2], -5) == 0
    assert possible_change([], -4) == 0
